new_func = '''export const getPopularSearches = async (limit: number = 10, period: PopularSearchPeriod = 'week'): Promise<PopularSearchResult[]> => {
  const now = new Date();
  let startDate: Date | undefined = undefined;

  switch (period) {
    case 'today':
      startDate = new Date(now.getFullYear(), now.getMonth(), now.getDate());
      break;
    case 'week':
      startDate = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
      break;
    case 'month':
      startDate = new Date(now.getFullYear(), now.getMonth() - 1, now.getDate());
      break;
    case 'all':
    default:
      startDate = undefined;
  }

  const where: any = {
    query: { not: '' },
  };
  if (startDate) {
    where.createdAt = { gte: startDate };
  }

  const popularSearches = await prisma.searchHistory.groupBy({
    by: ['query'],
    where,
    _count: {
      query: true,
    },
    _max: {
      createdAt: true,
    },
    orderBy: {
      _count: {
        query: 'desc',
      },
      _max: {
        createdAt: 'desc',
      },
    },
    take: limit,
  });

  return popularSearches.map(item => ({
    query: item.query,
    count: item._count.query,
    lastSearched: item._max.createdAt!,
  }));
};'''

